from primitive_api import (
    get_task_context,
    inspect_current_view,
    detect_objects,
    query_inventory,
    check_progress_public,
)

task_ctx = get_task_context()
start_view = inspect_current_view(label="initial_view", remember=True)

def compact(obj):
    return {
        k: obj.get(k)
        for k in (
            "objectId", "objectType", "name", "distance",
            "visible", "pickupable", "receptacle", "toggleable",
            "isPickedUp", "isDirty", "isToggled"
        )
        if k in obj
    }

target_views = {
    q: [compact(o) for o in detect_objects(q)]
    for q in ("SoapBar", "Soap", "SinkBasin", "Sink", "Faucet", "CounterTop")
}

print({
    "task": task_ctx,
    "pose": start_view.get("observation", {}).get("agent"),
    "inventory": query_inventory(),
    "targets_visible": target_views,
    "visible_count": len(start_view.get("visible_objects", [])),
    "progress": check_progress_public(),
    "frame": start_view.get("frame"),
})

from primitive_api import (
    observe, detect_objects, query_inventory, ground_object, query_object_state,
    approach_object, locate_object, put_object, toggle_object, pickup_object,
    pickup_located_object, place_held_object, inspect_current_view,
    check_progress_public, check_success
)

start = observe()
log = []

def ok(result):
    return bool(result) and result.get("observation_after", {}).get("lastActionSuccess", False)

def note(name, result):
    log.append({
        "action": name,
        "ok": ok(result),
        "error": result.get("observation_after", {}).get("errorMessage", "")
        if isinstance(result, dict) else "not attempted"
    })

inventory = query_inventory()
sinks = detect_objects("SinkBasin")

if inventory and sinks:
    sink = ground_object(sinks[0]["objectId"])
    result = put_object(inventory[0], sink)
    note("put_soap_in_sink", result)

    if not ok(result):
        approach_object(sink, max_steps=3, stop_distance=1.0)
        sinks = detect_objects("SinkBasin")
        if not sinks:
            located = locate_object(
                "SinkBasin", aliases=["Sink"],
                support_queries=["Faucet", "CounterTop"],
                search_budget=10, include_tilts=True
            )
            sinks = [located["current_object"]] if located.get("visible_now") else []
        if sinks:
            result = put_object(query_inventory()[0], ground_object(sinks[0]["objectId"]))
            note("put_soap_in_sink_retry", result)

